datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int      @id @default(autoincrement())
  username String   @unique
  comments Comment[]
}

model Post {
  id       Int      @id @default(autoincrement())
  title    String
  comments Comment[]
}

model Comment {
  id             Int       @id @default(autoincrement())
  content        String
  postId         Int
  post           Post      @relation(fields: [postId], references: [id])
  authorId       Int
  author         User      @relation(fields: [authorId], references: [id])
  parentId       Int?      @unique
  parent         Comment?  @relation("CommentChildren", fields: [parentId], references: [id], onDelete: Cascade)
  children       Comment[] @relation("CommentChildren")
}

app nestedComments {
  wasp: {
    version: "^0.16.8"
  },
  title: "nested-comments"
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

route PostRoute {
  path: "/post/:postId",
  to: PostPage
}
page PostPage {
  component: import { PostPage } from "@src/PostPage"
}

query getPosts {
  fn: import { getPosts } from "@src/queries.js",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/queries.js",
  entities: [Comment, Post, User]
}

action createComment {
  fn: import { createComment } from "@src/actions.js",
  entities: [Comment, Post, User]
}

action deleteComment {
  fn: import { deleteComment } from "@src/actions.js",
  entities: [Comment]
}

seed devSeed {
  fn: import { devSeed } from "@src/seed.js"
}

/**
 * Returns every post.
 * Each element includes `id` (number) and `title` (string).
 */
export const getPosts = async (_args, context) => {
  const posts = await context.entities.Post.findMany({
    orderBy: { id: 'asc' },
    select: {
      id: true,
      title: true,
    },
  });
  return posts;
};

/**
 * Returns the comments for a given post as a nested tree.
 *
 * Each node has exactly these keys:
 *   id (number), content (string), authorUsername (string),
 *   parentId (number | null), children (array of nodes)
 *
 * Sibling nodes are ordered by ascending `id` at every level.
 */
export const getCommentTree = async (args, context) => {
  const { postId } = args;

  // Fetch every comment for this post (at every depth) together with its
  // author, ordered by ascending id so we can build the tree deterministically.
  const comments = await context.entities.Comment.findMany({
    where: { postId },
    orderBy: { id: 'asc' },
    select: {
      id: true,
      content: true,
      parentId: true,
      author: {
        select: { username: true },
      },
    },
  });

  // Build a flat map of every node keyed by id.
  const nodesById = new Map();
  for (const c of comments) {
    nodesById.set(c.id, {
      id: c.id,
      content: c.content,
      authorUsername: c.author.username,
      parentId: c.parentId,
      children: [],
    });
  }

  // Assemble the tree: attach each node to its parent's `children`, or collect
  // it as a top-level node when it has no parent.
  const topLevel = [];
  for (const c of comments) {
    const node = nodesById.get(c.id);
    if (c.parentId === null) {
      topLevel.push(node);
    } else {
      const parent = nodesById.get(c.parentId);
      if (parent) {
        parent.children.push(node);
      } else {
        // Orphan (shouldn't happen with cascade delete) — treat as top-level.
        topLevel.push(node);
      }
    }
  }

  // Because we iterated comments in ascending-id order, both `topLevel` and
  // every `children` array are already sorted by ascending id.
  return topLevel;
};

/**
 * Creates a comment on a post, authored by a user (looked up by username),
 * optionally as a reply to an existing comment.
 *
 * Args: { postId: number, authorUsername: string, content: string, parentId?: number | null }
 * Returns the created comment object (must include `id`).
 */
export const createComment = async (args, context) => {
  const { postId, authorUsername, content, parentId } = args;

  // Look up the author by username.
  const author = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!author) {
    throw new Error(`User with username "${authorUsername}" not found`);
  }

  // Verify the post exists.
  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new Error(`Post with id ${postId} not found`);
  }

  // If a parentId is provided, verify the parent comment exists and belongs
  // to the same post (keeps the tree consistent).
  if (parentId != null) {
    const parent = await context.entities.Comment.findUnique({
      where: { id: parentId },
    });
    if (!parent) {
      throw new Error(`Parent comment with id ${parentId} not found`);
    }
  }

  const comment = await context.entities.Comment.create({
    data: {
      content,
      postId,
      authorId: author.id,
      parentId: parentId ?? null,
    },
  });

  return comment;
};

/**
 * Deletes a comment AND all of its descendant replies (cascade).
 *
 * Args: { commentId: number }
 *
 * We explicitly collect every descendant via BFS and delete them all in one
 * batch so no orphaned replies remain, regardless of database-level cascade
 * support.
 */
export const deleteComment = async (args, context) => {
  const { commentId } = args;

  // Collect the target comment and all of its descendants recursively.
  const toDelete = new Set([commentId]);
  let frontier = [commentId];

  while (frontier.length > 0) {
    const children = await context.entities.Comment.findMany({
      where: { parentId: { in: frontier } },
      select: { id: true },
    });

    const newIds = children
      .map((c) => c.id)
      .filter((id) => !toDelete.has(id));

    newIds.forEach((id) => toDelete.add(id));
    frontier = newIds;
  }

  // Delete the entire subtree (the comment itself plus all descendants).
  await context.entities.Comment.deleteMany({
    where: { id: { in: [...toDelete] } },
  });
};

